"""Offline interactive navigation and bounded final TRACE image-loss explorer."""
import json
from pathlib import Path
import pandas as pd
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'retrospective_20261102'
data={k:json.loads(pd.read_csv(OUT/n).to_json(orient='records',double_precision=15)) for k,n in [('fits','PHASE3_FIT_LEDGER.csv'),('images','TRACE_IMAGE_UTILITY.csv'),('groups','TRACE_COMPONENT_UTILITY.csv')]}
html='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Tyre project evidence explorer</title>
<style>:root{color-scheme:light;--ink:#183c49;--teal:#1a877e;--muted:#586d76}*{box-sizing:border-box}body{margin:0;background:#f3f6f6;font:16px/1.55 system-ui;color:var(--ink)}main{max-width:1200px;margin:auto;padding:30px 24px 60px}header{background:#183c49;color:white;padding:28px;border-radius:18px}h1{margin:0;font-size:clamp(28px,4vw,43px);line-height:1.15}h2{font-size:25px;margin:28px 0 10px}p{max-width:90ch}.eyebrow{letter-spacing:.12em;font-size:12px;color:#b8dcd6}a{color:#12685f}header a{color:#b8e6dc}.metrics{display:flex;gap:26px;flex-wrap:wrap;margin-top:18px}.metrics b{font-size:27px;display:block}.metrics span{font-size:13px}section{background:white;border:1px solid #dce5e4;border-radius:14px;padding:22px;margin-top:20px}select,input,button{font:inherit;padding:8px 12px;border:1px solid #b8cbca;border-radius:8px;background:white;color:var(--ink)}label{margin-right:10px;display:inline-flex;gap:8px;align-items:center;flex-wrap:wrap}.filters{display:flex;gap:10px;flex-wrap:wrap;margin:15px 0}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(250px,1fr));gap:12px}.card{border-left:4px solid var(--teal);background:#f3f8f7;padding:15px;border-radius:8px}.card h3{margin:0 0 8px;font-size:19px}.card small{color:var(--muted)}.note{color:var(--muted);font-size:14px}.tablewrap{overflow:auto}table{width:100%;border-collapse:collapse;font-size:14px}th,td{text-align:left;padding:10px;border-bottom:1px solid #dfe8e7}td:first-child{max-width:300px;overflow-wrap:anywhere}th{white-space:nowrap}.bars{display:grid;gap:10px}.barrow{display:grid;grid-template-columns:minmax(200px,1fr) 2fr 65px;gap:10px;align-items:center;font-size:14px}.track{background:#e9efee;border-radius:5px;height:16px}.fill{height:100%;background:var(--teal);border-radius:5px}img{width:100%;height:auto}button{cursor:pointer}button:disabled{opacity:.4;cursor:default}@media(max-width:600px){main{padding:14px}section,header{padding:17px}.barrow{grid-template-columns:1fr 1fr 55px;font-size:12px}}</style>
<main><header><div class="eyebrow">RESEARCH RECORD · 2 NOVEMBER 2026</div><h1>What the tyre project has taught us</h1><p>Useful geometry and texture reconstruction. Mileage-classifier transfer remains unresolved. Every original model selection is preserved.</p><div class="metrics"><span><b>570</b>existing photos</span><span><b>7</b>Phase3 fit families</span><span><b>10</b>measured fit executions</span><span><b>600</b>measured Phase3 epochs</span></div><p><a href="../phase3ProjectRetrospective.md">Full project analysis</a> · <a href="../phase3TRACEComponentReview.md">New TRACE component review</a></p></header>
<section><h2>Follow each model family</h2><p class="note">The counts exclude disposable engineering updates. NB13A resumed NB13; NB24 ran the NB22 stage. These are connected studies using the same photographs.</p><label>Family <select id="family"><option value="all">All seven families</option></select></label><div id="cards" class="cards"></div></section>
<section><h2>TRACE: where reconstruction improves</h2><p>Final epoch60, clean view0, original hidden-tile plan. Bars show reduction in mean masked loss against the visible-band control, on the same common support.</p><div class="filters"><label>Role <select id="role"><option value="all">All roles</option><option value="train">Train</option><option value="validation">Validation</option><option value="test">Historical test</option></select></label></div><div id="bars" class="bars"></div><p class="note">Components preserve conservative source relationships. These are descriptive improvements on previously inspected data, not independent new-tyre or physical-wear validation.</p></section>
<section><h2>Inspect the 570 image records</h2><p>Every image improves against all three masked controls for the recorded plan. Some test images improve by less than5%. None of this changes TRACE's failed overall diversity gate or selected=None.</p><div class="filters"><label>Search <input id="search" placeholder="Source image or component"></label><label><input type="checkbox" id="below">Show gain below5% against any control</label></div><p id="count" aria-live="polite"></p><div class="tablewrap"><table><thead><tr><th>Source image</th><th>Role</th><th>Masked loss</th><th>Minimum control gain</th><th>Local gain</th></tr></thead><tbody id="rows"></tbody></table></div><div class="filters"><button id="previous">Previous</button><button id="next">Next</button></div><p class="note">Minimum control gain is min(1−model/control) over channel mean, position mean and visible-band mean for that image. It differs from the aggregate visible-band bars. No confidence intervals treat these correlated photos as independent subjects.</p><p><a href="TRACE_IMAGE_UTILITY.csv">Full image CSV</a> · <a href="TRACE_COMPONENT_UTILITY.csv">Component CSV</a> · <a href="CONSUMED_SCIENCE_INPUTS.csv">Exact input hashes</a></p></section>
<section><h2>Cross-project findings</h2><img src="figures/Project_Findings.png" alt="Descriptive selection transfer, probability loss, diversity rejection and reconstruction gains"><p class="note">Different protocols and representation dimensions are labeled separately. This is not a matched architecture ranking. The full Markdown report records each source and limitation.</p></section>
<section><h2>Evidence boundary</h2><p>New analysis is local and has not been uploaded to HF. Original experiments retain their previously verified pinned HF evidence. This review performed no fitting, model forwards, new photo acquisition or workstation changes.</p><a href="README.md">Files and metric dictionary</a></section></main>
<script type="application/json" id="data">__DATA__</script><script>
const data=JSON.parse(document.getElementById('data').textContent),el=id=>document.getElementById(id);let page=0;
const minGain=r=>Math.min(r.gain_channel_mean,r.gain_position_mean,r.gain_visible_band_mean);
function filterImages(role='all',query='',below=false){query=query.toLowerCase();return data.images.filter(r=>(role==='all'||r.role===role)&&(!query||(r.image_id+' '+r.component).toLowerCase().includes(query))&&(!below||!r.passes_5pct_all_controls)).sort((a,b)=>minGain(a)-minGain(b)||a.image_id.localeCompare(b.image_id));}
function textNode(tag,text){const e=document.createElement(tag);e.textContent=text;return e;}
function renderCards(){el('cards').replaceChildren();for(const r of data.fits.filter(r=>el('family').value==='all'||r.family===el('family').value)){const card=document.createElement('article');card.className='card';const link=textNode('a','Read the original result');link.href='../'+r.source;card.append(textNode('h3',r.family),textNode('small',r.fits+' fit execution(s) · '+r.fit_notebook),textNode('p',r.result),textNode('p','Selection: '+r.selected),link);el('cards').append(card);}}
function render(){const role=el('role').value;el('bars').replaceChildren();for(const r of data.groups.filter(r=>role==='all'||r.role===role)){const row=document.createElement('div');row.className='barrow';const track=document.createElement('div'),fill=document.createElement('div');track.className='track';fill.className='fill';fill.style.width=Math.max(0,Math.min(100,r.gain_visible_band_mean*100))+'%';track.append(fill);row.append(textNode('span',r.role+' / '+r.component.replace('tyre:','')+' (n='+r.images+')'),track,textNode('b',(r.gain_visible_band_mean*100).toFixed(2)+'%'));el('bars').append(row);}
const rows=filterImages(role,el('search').value,el('below').checked),pages=Math.max(1,Math.ceil(rows.length/12));page=Math.min(Math.max(0,page),pages-1);el('count').textContent=rows.length+' image records · page '+(page+1)+' / '+pages;el('rows').replaceChildren();for(const r of rows.slice(page*12,page*12+12)){const row=document.createElement('tr');for(const value of [r.image_id,r.role,r.masked_model.toFixed(6),(minGain(r)*100).toFixed(2)+'%',(r.local_gain*100).toFixed(2)+'%'])row.append(textNode('td',value));el('rows').append(row);}el('previous').disabled=page===0;el('next').disabled=page===pages-1;}
for(const r of data.fits){const option=textNode('option',r.family);option.value=r.family;el('family').append(option);}el('family').addEventListener('change',renderCards);
for(const id of ['role','search','below'])el(id).addEventListener(id==='search'?'input':'change',()=>{page=0;render();});el('next').onclick=()=>{page++;render();};el('previous').onclick=()=>{page--;render();};
globalThis.retrospectiveAudit={filterImages,minGain,data};renderCards();render();
</script></html>'''
payload=json.dumps(data,separators=(',',':'),ensure_ascii=True,allow_nan=False).replace('<','\\u003c')
(OUT/'Project_Evidence_Explorer.html').write_text(html.replace('__DATA__',payload),encoding='utf-8',newline='\n')
print('Offline explorer written; no external scripts or network dependencies.')
